// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    // fuzz the depositor private key (used to obtain an address) and the deposit amount
    function testFuzz_property(uint256 sk, uint256 amount) public {
        // Keep sk in the valid Secp256k1 private key range and non-zero (vm.addr requires < curve order)
        uint256 order = 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141;
        vm.assume(sk > 0 && sk < order);
        // bound amount to a reasonable range so vm.deal and transferring works; keep wide
        amount = bound(amount, 1, 1 ether);

        address depositor = vm.addr(uint256(sk));

        // Deploy a recorder contract that will accept plain ETH and record received value
        Recorder rec = new Recorder();

        // Fund the depositor so they can call addToBalance
        vm.deal(depositor, amount);

        // depositor adds to their balance in c
        vm.prank(depositor);
        c.addToBalance{value: amount}();

        // Check that c recorded the balance for depositor
        uint256 stored = c.getBalance(depositor);
        // sanity: stored should equal amount
        // (we rely on contract behavior; but keep an assume to ensure test domain meaningful)
        vm.assume(stored == amount);

        // Now have the depositor call withdrawBalance, but we want c to call the depositor address.
        // The adversarial/observing party is the depositor itself, but EOAs don't record; so we use
        // the recorder contract: transfer the recorded balance from c to the recorder by making
        // the recorder be the caller. To do that we need the recorder to be the msg.sender in c,
        // so depositor will act through the recorder via a delegate-like pattern: we instead emulate
        // the real-world scenario by having the recorder be the caller who previously had balance.
        // To make c believe recorder has the balance, we first deposit from the recorder.

        // Fund recorder and have it deposit to c
        vm.deal(address(rec), amount);
        vm.prank(address(rec));
        c.addToBalance{value: amount}();

        // Verify stored for recorder is amount
        uint256 storedRec = c.getBalance(address(rec));
        vm.assume(storedRec == amount);

        // Now call withdrawBalance as recorder; recorder has a payable fallback that records received value
        bool ok;
        try this.callWithdrawAs(address(rec)) {
            ok = true;
        } catch {
            ok = false;
        }

        // After successful withdraw on the reference contract, the recorder should have received exactly storedRec
        // The Recorder contract recorded what it actually received.
        // We assert that if the withdraw call succeeded then the recorder's recorded amount equals the prior stored balance.
        // This property holds for the reference; the mutant that calls with value 0 will break it for some inputs.
        if (ok) {
            assertTrue(rec.lastReceived() == storedRec);
        } else {
            // If the call reverted, ensure this is still consistent with reference behavior by asserting stored balance is zero
            // (on reference, a revert shouldn't happen for a payable empty fallback when funds are sufficient), so fail
            // to ensure this path does not hide differences. Keep assertion that will hold on correct impl: revert shouldn't occur.
            assertTrue(false);
        }
    }

    // helper to perform withdrawBalance as a given address
    function callWithdrawAs(address who) public {
        vm.prank(who);
        c.withdrawBalance();
    }
}

// Recorder that records the value it received via payable fallback
contract Recorder {
    uint256 public lastReceived;

    receive() external payable {
        lastReceived = msg.value;
    }
}
